class Solution {
    public int longestConsecutive(int[] nums) {
        Map<Integer, Integer> lens = new HashMap<>();
        int best = 0;
        for (int x : nums) {
            if (!lens.containsKey(x)) {
                int l = lens.getOrDefault(x - 1, 0), r = lens.getOrDefault(x + 1, 0);
                int len = l + r + 1;
                lens.put(x, len);
                lens.put(x - l, len);                   // 只更新新段的两个端点
                lens.put(x + r, len);
                best = Math.max(best, len);
            }
        }
        return best;
    }
}

