            if (!lens.count(x)) {
                int l = lens.count(x - 1) ? lens[x - 1] : 0;
                int r = lens.count(x + 1) ? lens[x + 1] : 0;
                int len = l + r + 1;
                lens[x] = len;
                lens[x - l] = len;                      // 只更新新段的两个端点
                lens[x + r] = len;
                best = max(best, len);
            }
        }
        return best;
    }
};

