build(a, snap) {
    const set = [...new Set(a.nums)], has = new Set(set);
    let best = 0, bestRun = [];
    const view = (cur, run, skip) => [{ t: "chips", label: "集合（已去重）", items: set.map((v) => ({ v, cls: v === cur ? (skip ? "w" : "a") : run && run.includes(v) ? "e" : !run && bestRun.includes(v) ? "c" : "" })) }];
    snap("建集合", `把 nums 里的数放进集合，重复的只留一个，共 ${set.length} 个。`, view(null), { at: "init", facts: [["最长", 0]] });
    for (const x of set) {
      if (has.has(x - 1)) {
        snap("跳过", `${x}：${x - 1} 在集合里，说明 ${x} 不是一段的起点。它会被前面的起点数到，<b>跳过</b>。`, view(x, null, true), { at: "skip", kind: "warn", facts: [["最长", best]] });
        continue;
      }
      const run = [x];
      snap("起点", `${x}：${x - 1} 不在集合里，${x} 是起点，从这里往上数。`, view(x, run), { at: "start", facts: [["最长", best], ["当前长度", 1]] });
      let y = x;
      while (has.has(y + 1)) {
        y++; run.push(y);
        snap("往上数", `${y} 在集合里，接上。当前这段是 ${x} 到 ${y}，长度 ${run.length}。`, view(x, run), { at: "count", facts: [["最长", best], ["当前长度", run.length]] });
      }
      const improved = run.length > best;
      if (improved) { best = run.length; bestRun = run.slice(); }
      snap("这段结束", `${y + 1} 不在集合里，这段到此为止，长度 ${run.length}。` + (improved ? `更新最长为 <b>${best}</b>。` : `没有超过当前最长 ${best}。`), view(null, run), { at: "best", facts: [["最长", best], ["当前长度", run.length]] });
    }
    snap("完成", `所有数都看过了，最长连续序列的长度是 <b>${best}</b>（${bestRun[0]} 到 ${bestRun[bestRun.length - 1]}）。`, view(null), { at: "done", kind: "ok", ans: best, facts: [["最长", best]] });
  }

