      snap("开始", "lens 一开始是空的。逐个处理 nums 里的数。", view(-1, null, false), { at: "init", ...f() });
      nums.forEach((x, i) => {
        if (lens.has(x)) { snap("重复", `${x} 已经处理过了，跳过。`, view(i, null, true), { at: "dup", kind: "warn", ...f() }); return; }
        const l = lens.get(x - 1) || 0, r = lens.get(x + 1) || 0, len = l + r + 1;
        lens.set(x, len); lens.set(x - l, len); lens.set(x + r, len);
        best = Math.max(best, len);
        const left = l ? `左边是一段 ${x - l}…${x - 1}（长 ${l}）` : `左边没有 ${x - 1}`, right = r ? `右边是一段 ${x + 1}…${x + r}（长 ${r}）` : `右边没有 ${x + 1}`;
        snap("连起来", `${x}：${left}，${right}。连起来是 ${x - l}…${x + r}，长度 ${l} + ${r} + 1 = <b>${len}</b>。把两个端点 ${x - l} 和 ${x + r} 都更新成 ${len}。`, view(i, [x, x - l, x + r], false), { at: ["dup", "join"], ...f() });
      });
      snap("完成", `全部处理完，最长连续序列的长度是 <b>${best}</b>。每个数只处理一次，时间 O(n)。`, view(nums.length, null, false), { at: "done", kind: "ok", ans: best, ...f() });
